# Chaque ingrédient : (clé du catalogue, quantité affichée, unité, grammes pour TOUTE la recette).
# Les grammes servent au calcul nutritionnel à partir de la table Ciqual 2020 (ANSES).

def R(id, title, meal, servings, prep, cook, difficulty, summary, ingredients, steps, substitutions=()):
    return dict(id=id, title=title, meal=meal, servings=servings, prep=prep, cook=cook, difficulty=difficulty,
                summary=summary, ingredients=ingredients, steps=steps, substitutions=list(substitutions))

